from rosterkit.errors import ProjectError

def _sort_key(student):
    return (student.last_name, student.first_name)

def _format_row(number, team):
    names = " | ".join(pupil.display_name for pupil in team)
    return f"Row {number}: {names}"

# ---
def seat_rows(students, per_row):
    if per_row <= 0 or not students:
        raise ProjectError("need students and seats")
    ordered = sorted(students, key=_sort_key)
    rows = [ordered[pos:pos + per_row]
            for pos in range(0, len(ordered), per_row)]
    return [_format_row(num, row)
            for num, row in enumerate(rows, 1)]

